Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

(* [comment removed for export] *)
Definition PRw (wEnd mB c w : Z) : Z -> Prop := fun j =>
  (1 <= j < wEnd) \/ (exists c' w', mB <= c' /\ ((c' < c /\ 1 <= w' < wEnd) \/ (c' = c /\ 1 <= w' < w)) /\ j = rv_idx c' w').

Section FM.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).

  Variables (x1 x5 x6 x7 x8 x9 x10 x11 x12 x15 x17 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word).
  Variables (m : fmem) (WK tl : Z) (rank : list Z).
  Variable POST : machine_state -> Prop.
  Hypothesis HWK : 0 < WK /\ WK + 2124 <= 2^47.
  Hypothesis HTL : 1 <= tl <= 12.
  Hypothesis LRK : length rank = 13%nat.
  Hypothesis RKR : forall i, 0 <= i < 13 -> 0 <= Znth i rank <= 256.
  Hypothesis RKA : u32arr psegs m (WK + 624) (map (Z_to_bv 64) rank).

  Lemma fm_loop : forall f w r (x16 : word), find_maxW f w rank = Ok r -> 0 <= w <= tl ->
    (forall y16 : word, evt psegs POST (MS (mkR x1 sp gp tp x5 x6 x7 x8 x9 x10 x11 x12 (Z_to_bv 64 (tl - r + 1)) (Z_to_bv 64 (r - 1)) x15 y16 x17 (Z_to_bv 64 (WK + 624)) x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 0x13b58) fc None m (seg_rom psegs))) ->
