  Notation SINV m1 rs0 sorted := (u32arr psegs m1 (WK + 676) (map (Z_to_bv 64) rs0) /\ length rs0 = 15%nat
                           /\ u8arr psegs m1 (WK + 736) (omerge js sorted) /\ length sorted = 256%nat
                           /\ munch [(WK + 676, WK + 992)] m m1 /\ wmono psegs m m1 /\ mem_inv psegs m1).

  Lemma so2_loop : forall f s rs0 sorted m1 r (x5 x6 x7 : word),
    sort2 f s ws rs0 sorted = Ok r -> Z.of_nat f = nbS - s -> 0 <= s < nbS ->
    (forall i, 0 <= i < 15 -> 0 <= Znth i rs0 <= 256) -> SINV m1 rs0 sorted ->
    (forall m2 rs0' sorted' (y5 y6 y7 : word), r = (rs0', sorted') -> SINV m2 rs0' sorted' ->
