    (forall m2 rv' (y12 y16 y17 : word), r = rv' -> VINV m2 rv' wEnd ->
       evt psegs POST (MS (mkR x1 sp gp tp x5 x6 x7 x8 x9 x10 (Z_to_bv 64 (WK + 624 + 4 * wEnd)) y12 x13 (Z_to_bv 64 (WK + 624 + 4 * wEnd)) x15 y16 y17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 0x13c5c) fc None m2 (seg_rom psegs))) ->
