Section RVR.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).

  Variables (x1 x6 x8 x9 x13 x15 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word).
  Variables (m : fmem) (WK wEnd mB T : Z).
  Variable POST : machine_state -> Prop.
  Hypothesis HWK : 0 < WK /\ WK + 2124 <= 2^47.
  Hypothesis HWE : 2 <= wEnd <= 13.
  Hypothesis HMB : 1 <= mB /\ T - mB <= 11.
  Notation WINV m1 rv c w := (rv_at m1 WK rv (PRw wEnd mB c w) /\ length rv = 156%nat
                           /\ (forall j, 1 <= j < wEnd -> 0 <= Znth j rv < 2^31)
                           /\ munch [(WK, WK + 624)] m m1 /\ wmono psegs m m1 /\ mem_inv psegs m1).

  Lemma rvr_inner : forall f c w rv m1 r (x5 x7 : word),
    rank_val_row f c w rv = Ok r -> Z.of_nat f = wEnd - w -> 1 <= w < wEnd -> mB <= c <= T - mB -> WINV m1 rv c w ->
    (forall m2 rv' (y5 y7 : word), r = rv' -> WINV m2 rv' c wEnd ->
       evt psegs POST (MS (mkR x1 sp gp tp y5 x6 y7 x8 x9 (Z_to_bv 64 (WK + 4 * wEnd)) (Z_to_bv 64 (T - mB + 1)) (Z_to_bv 64 (WK + 4)) x13 (Z_to_bv 64 (52 * c)) x15 (Z_to_bv 64 c) (Z_to_bv 64 (WK + 4 * wEnd)) x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 0x13c9c) fc None m2 (seg_rom psegs))) ->
